parameters.jsCode:
// Ensure we handle either raw string JSON or pre-parsed object output from the AI node
const inputData = $input.first().json;

// Extract the AI's response text (handles standard n8n LLM node output schema)
let rawOutput = inputData.text || inputData.output || inputData;

// If the output is a string, strip code block markdown ticks if present and parse
if (typeof rawOutput === 'string') {
  const cleanedText = rawOutput.replace(/```json\n?|\n?```/g, '').trim();
  rawOutput = JSON.parse(cleanedText);
}

// Return structured fields for downstream nodes
return [
  {
    json: {
      leadRanking: rawOutput.leadRanking || 'COLD',
      reasoning: rawOutput.reasoning || '',
      icebreaker: rawOutput.icebreaker || '',
      confidenceLevel: Number(rawOutput.confidenceLevel) || 0
    }
  }
];

// Process incoming n8n items
const processedLeads = items.map(item => {
  const json = item.json;

  // Extract current position details safely
  const currentPos = (json.currentPosition && json.currentPosition.length > 0) 
    ? json.currentPosition[0] 
    : {};

  return {
    json: {
      id: json.id || json.publicIdentifier,
      fullName: `${json.firstName || ''} ${json.lastName || ''}`.trim(),
      linkedinUrl: json.linkedinUrl,
      openToWork: Boolean(json.openToWork),
      headline: json.headline || null,
      location: json.location?.parsed?.text || json.location?.linkedinText || null,
      currentRole: currentPos.position || null,
      currentCompany: currentPos.companyName || currentPos.company?.name || null,
      about: json.about || null,
      topSkills: Array.isArray(json.topSkills) 
        ? json.topSkills 
        : (json.skills ? json.skills.map(s => s.name).slice(0, 5) : [])
    }
  };
});

return processedLeads;

// Extract all full names dynamically from the input items
const leadNames = $input.all().map(item => item.json.fullName).filter(Boolean);

// Create a bulleted list of the lead names
const namesList = leadNames.map(name => `• ${name}`).join('\n');

// Draft the email notification message
const subject = `New Warm Leads Identified (${leadNames.length})`;
const emailBody = `Hi Team,

Great news! We have identified a new set of ${leadNames.length} warm leads from our latest candidate sourcing workflow. Please review their profiles in the dashboard so we can begin our outreach and nurturing sequence.

Warm Leads:
${namesList}

Best regards,
Automated Sourcing Pipeline`;

// Return the structured object for downstream email nodes (e.g., Gmail, Outlook, or SMTP)
return [
  {
    json: {
      subject: subject,
      emailBody: emailBody,
      totalLeads: leadNames.length,
      leadNames: leadNames
    }
  }
];

return $input.all().map(item => {
  // Parse the string inside the 'output' field into actual JSON
  const parsedData = JSON.parse(item.json.output);

  return {
    json: {
      subject: parsedData.subject,
      emailBody: parsedData.emailBody
    }
  };
});

// Extract incoming items from the array
const items = $input.all();
const totalLeads = items.length;

// Map out each candidate dynamically using available fields
const leadList = items.map((item, index) => {
  const json = item.json;

  // Extract subject line as a proxy for the context/role, fallback gracefully if not found
  const topic = json.subject || "Outreach Email Drafted";
  const candidateId = json.id || "N/A";

  return `*${index + 1}. Candidate ID:* \`${candidateId}\`\n📌 *Subject:* "${topic}"`;
}).join('\n\n');

// Draft the Slack notification
const slackMessage = `🚀 *New Hot Lead Outreach Ready!*

Hi Team,

We have finalized personalized email drafts for *${totalLeads}* high-priority ${totalLeads === 1 ? 'lead' : 'leads'}. The outreach copy is generated and queued for review/dispatch.

*Summary of Prepared Emails:*
${leadList}

Please review the pipeline dashboard to approve and monitor delivery status.

Best regards,
*LeadGen Automation Bot*`;

return [
  {
    json: {
      totalLeads: totalLeads,
      text: slackMessage
    }
  }
];
